public class Main {
    public static void main(String[] args) {
        JalankanTest.kelas(TodoTest.class);
    }
}

class TodoTest {
    @Test
    void todoBaruBelumSelesai() {
        Todo t = new Todo(1, "Belajar");
        assertFalse(t.isSelesai());
    }
}

class Todo {
    private final int id;
    private final String judul;
    private boolean selesai;

    Todo(int id, String judul) {
        this.id = id;
        this.judul = judul;
    }

    int getId() {
        return id;
    }

    String getJudul() {
        return judul;
    }

    boolean isSelesai() {
        return selesai;
    }

    void selesaikan() {
        selesai = true;
    }

    @Override
    public String toString() {
        return id + ". [" + (selesai ? "x" : " ") + "] " + judul;
    }
}

