import java.util.*;

import org.junit.jupiter.api.*;

import static org.junit.jupiter.api.Assertions.*;

public class Main {
    public static void main(String[] args) {
        JalankanTest.kelas(DiskonTest.class);
    }
}

class DiskonTest {
    @Test
    void belanjaKecilTanpaDiskon() {
        assertEquals(50000, Diskon.hitung(50000));
    }

    @Test
    void belanjaPasSeratusRibuDapatDiskon() {
        assertEquals(90000, Diskon.hitung(100000));
    }

    @Test
    void belanjaBesarDapatDiskon() {
        assertEquals(180000, Diskon.hitung(200000));
    }
}

class Diskon {
    // potongan 10% untuk belanja minimal 100000
    static int hitung(int total) {
        if (total >= 100000) {
            return total - total / 10;
        }
        return total;
    }
}
